<html>
<head>
  <title>Podcast List</title>
  <style>
    body {
      font-family: sans-serif;
    }
    .container {
      display: flex;
      flex-direction: column;
      align-items: center;
    }
    input[type="text"] {
      width: 200px;
      padding: 10px;
      margin-bottom: 10px;
    }
    button {
      padding: 10px 20px;
      background-color: #4CAF50;
      color: white;
      border: none;
      cursor: pointer;
    }
    .episode {
      margin-bottom: 10px;
      padding: 10px;
      border: 1px solid #ccc;
      display: flex;
      justify-content: space-between;
    }
    .ethos-badge {
      width: 20px;
      height: 20px;
      margin-right: 5px;
      display: inline-block;
      vertical-align: middle;
    }
    audio {
      width: 100%;
      margin-bottom: 10px;
    }
  </style>
</head>
<body>
  <div class="container">
    <h1>Podcast List</h1>
    <input type="text" placeholder="Enter feed URL" />
    <button onclick="subscribe()">Subscribe</button>
    <div id="episodes"></div>
  </div>
  <script>
    function subscribe() {
      const urlInput = document.querySelector('input[type="text"]');
      const url = urlInput.value;
      fetch(`/api/subscribe?url=${encodeURIComponent(url)}`)
        .then(response => {
          if (!response.ok) {
            throw new Error(`HTTP error! Status: ${response.status}`);
          }
          return response.json();
        })
        .then(data => {
          const episodes = data.episodes;
          renderEpisodes(episodes);
        })
        .catch(error => {
          console.error(error);
          document.getElementById('episodes').innerHTML = `<p>An error occurred: ${error.message}</p>`;
        });
    }

    function renderEpisodes(episodes) {
      const episodesContainer = document.getElementById('episodes');
      episodesContainer.innerHTML = '';
      episodes.forEach(episode => {
        const episodeElement = document.createElement('div');
        episodeElement.classList.add('episode');
        episodeElement.innerHTML = `
          <h3>${episode.title}</h3>
          <p>Published: ${episode.pubDate}</p>
          <div class="ethos-badge">
            <span style="background-color: green; color: white; padding: 5px; border-radius: 50%;" 
              title="${episode.ethos}">
            </span>
          </div>
          <audio src="${episode.audioUrl}" controls></audio>
        `;
        episodesContainer.appendChild(episodeElement);
      });
    }
  </script>
</body>
</html>
